function parseGdTable(table) {
  return table.trim().split(/[\n;]/).filter((entry) => entry.length > 0).map((entry) => {
    const sep = entry.indexOf("|");
    return gd14(entry.slice(0, sep), entry.slice(sep + 1));
  });
}
