function buildAnimEffectNode(shapeId, duration, transition, allocateId) {
  const animId = allocateId();
  return {
    _type: "animEffect",
    "@_transition": transition,
    "@_filter": "fade",
    "p:cBhvr": {
      "p:cTn": {
        "@_id": String(animId),
        "@_dur": String(duration)
      },
      "p:tgtEl": {
        "p:spTgt": {
          "@_spid": shapeId
        }
      }
    }
  };
}
function buildAnimRotNode(shapeId, duration, preset, allocateId) {
  const animId = allocateId();
  const byAngle = preset === "spin" ? "21600000" : "300000";
  return {
    _type: "animRot",
    "@_by": byAngle,
    "p:cBhvr": {
      "p:cTn": {
        "@_id": String(animId),
        "@_dur": String(duration),
        "@_fill": "hold"
      },
      "p:tgtEl": {
        "p:spTgt": {
          "@_spid": shapeId
        }
      },
      "p:attrNameLst": {
        "p:attrName": "r"
      }
    }
  };
}
function buildAnimScaleNode(shapeId, duration, allocateId) {
  const animId = allocateId();
  return {
    _type: "animScale",
    "p:by": {
      "@_x": "125000",
      "@_y": "125000"
    },
    "p:cBhvr": {
      "p:cTn": {
        "@_id": String(animId),
        "@_dur": String(duration),
        "@_fill": "hold",
        "@_autoRev": "1"
      },
      "p:tgtEl": {
        "p:spTgt": {
          "@_spid": shapeId
        }
      }
    }
  };
}
function buildAnimPropertyNode(shapeId, duration, attrName, allocateId, keyframes) {
  const animId = allocateId();
  const tavLst = buildTavLstFromKeyframes(keyframes) ?? buildTavLstFromKeyframes(DEFAULT_OPACITY_KEYFRAMES);
  return {
    _type: "anim",
    "@_calcmode": "lin",
    "@_valueType": "num",
    "p:cBhvr": {
      "p:cTn": {
        "@_id": String(animId),
        "@_dur": String(duration),
        "@_fill": "hold"
      },
      "p:tgtEl": {
        "p:spTgt": {
          "@_spid": shapeId
        }
      },
      "p:attrNameLst": {
        "p:attrName": attrName
      }
    },
    "p:tavLst": tavLst
  };
}

